function test_spatial_condition_parity()
% Shared inputs generated by test_spatial_condition_parity.cjs.
cases=jsondecode(fileread(fullfile('output','spatial-condition-parity.json')));
for i=1:numel(cases)
    c=cases{i}; filename=[tempname() '.txt']; fid=fopen(filename,'w');fprintf(fid,'%s',c.text);fclose(fid);cleanup=onCleanup(@() delete(filename));
    failed=false;
    try
        p=StructFEProblem(filename);m=p.GetAnalysisModel();constraints=buildSpatialConstraints(m);
        if strcmp(p.mesh.analysisConfiguration.type,'static'),buildStaticLoad(m);end
        if ~c.valid,error('Test:AcceptedInvalid','Invalid fixture accepted: %s',c.name);end
        assert(numel(constraints.warnings)==c.warnings);
        for node=1:m.numberOfNodes
            G=m.nodalKinematics((node-1)*6+(4:6),:);expected=squeeze(c.projectors(node,:,:));
            assert(norm(full(G*G.')-expected,inf)<1e-9,['Rotation projector: ' c.name]);
        end
        if c.solve
            r=p.RunSelected();
            if strcmp(c.name,'axial-static'),assert(abs(r.nodalDisplacements(7)-1000*2/(2e11*.01))<1e-14);end
            if strncmp(c.name,'coupled-',8)
                if strcmp(p.mesh.analysisConfiguration.type,'modal')
                    assert(norm(r.nodalModeShapes(8,:)-2*r.nodalModeShapes(9,:),inf)<1e-10);
                else
                    assert(norm(r.nodalDisplacements(8,:)-2*r.nodalDisplacements(9,:),inf)<1e-10);
                end
            end
            if strcmp(p.mesh.analysisConfiguration.type,'transient')
                dt=p.mesh.analysisConfiguration.timeStep;force=buildTransientLoad(m,dt,3);type=m.forceBoundaryConditions(1,1);
                if type==11,expected=1000*sin(2*pi*10*(0:3)*dt);elseif type==13,expected=1000*ones(1,4);else,expected=[0 1000 0 0];end
                assert(norm(force(8,:)-expected,inf)<1e-9);
            end
        end
    catch err
        if c.valid || strcmp(err.identifier,'Test:AcceptedInvalid'),rethrow(err);end
        failed=true;
    end
    assert(c.valid || failed);fprintf('  %s: parity PASS\n',c.name);clear cleanup;
end
end
